/**
 * iOS WebKit 미디어 제스처 언락.
 *
 * iOS Safari는 `<audio>`/`<video>` **엘리먼트마다** "사용자 제스처 처리 중에 play()가 한 번
 * 호출된 적이 있는가"를 기억하고, 없으면 이후의 모든 play()를 `NotAllowedError`로 막는다.
 * 그런데 `playVideo()`는 스트림 URL(`/audios/:id/stream`)이나 DASH 매니페스트를 `await`로
 * 받아온 **뒤에** play()를 부르므로, 그 시점엔 이미 제스처 태스크 밖이라 첫 재생이 막힌다.
 * (증상: iPhone/iPad에서 재생 버튼을 처음 누르면 소리가 안 나고, 두 번째 누름 —
 *  `togglePlay`의 동기 play() — 부터 재생된다.)
 *
 * WebKit은 play()가 제스처 처리 중에 호출되기만 하면 **성공 여부와 무관하게** 그 엘리먼트의
 * 제스처 제약을 해제한다. 그래서 첫 `await` 이전(=아직 제스처 태스크 안)에 무음 소스로
 * play()를 한 번 불러 미리 언락해 둔다.
 */

/** 0.05초 무음 WAV(8kHz/mono/16bit, 844바이트). */
const SILENT_WAV =
  'data:audio/wav;base64,'

/**
 * 미디어 엘리먼트의 iOS 제스처 제약을 해제한다.
 * **반드시 사용자 제스처(click/touch) 핸들러 안에서, 첫 `await` 이전에 동기 호출해야 한다.**
 *
 * 이전 트랙의 src를 무음으로 갈아끼우므로 옛 곡이 잠깐 새어나오지 않는다. 곧바로 src를
 * 떼고 `load()`로 되돌리는데, `load()`는 방금 큐잉된 play/loadedmetadata/durationchange
 * 태스크까지 취소하므로 무음 WAV의 길이(0.05초)가 앱 상태(duration 등)에 새어들지 않는다.
 */
export function primeMediaElement(el: HTMLMediaElement | null | undefined): void {
  if (!el) return
  el.src = SILENT_WAV
  // 아래 load()가 이 play를 즉시 취소하므로 promise는 AbortError로 거절된다 — 반드시 삼킨다.
  void el.play().catch(() => {})
  el.removeAttribute('src')
  el.load()
}
